const filtersConfig: FiltersConfig = {
  // 1. Agrupar (rollUp) por la dimensi\xF3n con id 1 ('Regi\xF3n').
  //    Esto colapsar\xE1 la dimensi\xF3n 'Regi\xF3n', sumando sus valores.
  rollUp: [1],

  // 2. Filtrar la dimensi\xF3n con id 2 ('A\xF1o') para mostrar solo el item '2024'.
  filter: [
    {
      name: 2, // ID de la dimensi\xF3n 'A\xF1o'
      items: ['2024']
    }
  ]
};

// Aplicar los filtros al dataset.
